// Some portions generated by Claude
'use strict';

// Saved query results (ExecPlan .agent/execplan-query-tabs-g2.md, Part 2, M2): a query tab's result is persisted to
// its own row store, kept in the registry for that tab, and opened again by a later page of the same browser. Only
// one page at a time has a saved store open, and a store that no longer exists is never created again empty.

const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApi } = require('./query-load-more-harness.js');
const { loadWorker, fakeIndexedDB, realWorkerFactory } = require('./row-store-worker-harness.js');

const REGISTRY = 'rdf4j.workbench.row-store.v2:';
const DATABASE = 'rdf4j-workbench-row-store:';

function rows(from, to) {
    return Array.from({ length: to - from }, (_, index) => [{ type: 'literal', value: String(from + index) }]);
}

function values(batch) {
    return [...batch].map((row) => row[0].value);
}

function mapStorage() {
    const values = new Map();
    return {
        values,
        get length() { return values.size; },
        key(index) { return [...values.keys()][index] || null; },
        getItem(key) { return values.has(key) ? values.get(key) : null; },
        setItem(key, value) { values.set(key, String(value)); },
        removeItem(key) { values.delete(key); }
    };
}

/** A browser: one IndexedDB and one localStorage, shared by the pages it loads; each page is a fresh module. */
function browser() {
    const storage = fakeIndexedDB();
    const localStorage = mapStorage();
    const pages = [];
    return {
        storage,
        localStorage,
        page() {
            const pagehide = [];
            const loaded = loadApi({
                localStorage,
                addEventListener(type, listener) { if (type === 'pagehide') pagehide.push(listener); }
            });
            const workers = realWorkerFactory(storage);
            const page = Object.assign(loaded, {
                workers,
                options: { workerFactory: workers.factory, storageTimeout: 2000 },
                unload() { pagehide.forEach((listener) => listener({ persisted: false })); }
            });
            pages.push(page);
            return page;
        }
    };
}

function entryOf(localStorage, id) {
    const value = localStorage.getItem(REGISTRY + id);
    return value === null ? null : JSON.parse(value);
}

const KEPT = { scope: '["sha256:abc","","lmdb"]', tabId: 't1', owner: 'page-a', shownAt: 1, rows: 3 };

test('the worker opens a saved store again, and answers gone for a store that no longer exists', async () => {
    const storage = fakeIndexedDB();
    const scope = { indexedDB: storage.indexedDB, IDBKeyRange: storage.IDBKeyRange };
    const first = loadWorker(scope);
    assert.equal((await first.send({ requestId: 1, op: 'create', storeId: 'rows-a' })).ok, true);
    await first.send({ requestId: 2, op: 'append', storeId: 'rows-a', text: '["x"]\n["y"]', rowCount: 2 });

    const later = loadWorker(scope);
    const opened = await later.send({ requestId: 1, op: 'open', storeId: 'rows-a' });
    assert.equal(opened.ok, true, opened.error);
    assert.equal(opened.count, 2);
    assert.equal((await later.send({ requestId: 2, op: 'read', storeId: 'rows-a', start: 0, count: 5 })).text,
        '[["x"],["y"]]');
    assert.equal((await later.send({ requestId: 3, op: 'append', storeId: 'rows-a', text: '["z"]', rowCount: 1 }))
        .count, 3, 'Load more continues the saved rows');

    const missing = loadWorker(scope);
    const gone = await missing.send({ requestId: 1, op: 'open', storeId: 'rows-missing' });
    assert.equal(gone.ok, false);
    assert.equal(gone.gone, true);
    assert.ok(!storage.databases.has(DATABASE + 'rows-missing'), 'opening a deleted store does not create it empty');
    assert.equal((await missing.send({ requestId: 2, op: 'append', storeId: 'rows-missing', text: '["x"]',
        rowCount: 1 })).ok, false, 'and nothing can be written to it');
});

test('the worker names the browser error, so a full quota is told apart from a broken database', async () => {
    const storage = fakeIndexedDB();
    const worker = loadWorker({ indexedDB: storage.indexedDB, IDBKeyRange: storage.IDBKeyRange });
    await worker.send({ requestId: 1, op: 'create', storeId: 'rows-q' });
    const connection = storage.connections.find((candidate) => candidate.name === DATABASE + 'rows-q');
    const transaction = connection.transaction.bind(connection);
    connection.transaction = (names, mode) => {
        const writing = transaction(names, mode);
        if (mode === 'readwrite') {
            // The browser aborts a write that does not fit the quota.
            writing.error = { name: 'QuotaExceededError', message: 'The quota has been exceeded.' };
            writing.abort();
        }
        return writing;
    };
    const failed = await worker.send({ requestId: 2, op: 'append', storeId: 'rows-q', text: '["x"]', rowCount: 1 });
    assert.equal(failed.ok, false);
    assert.equal(failed.errorName, 'QuotaExceededError');
});

test('a small result is persisted and kept for its tab; a later page opens it again and continues it', async () => {
    const shared = browser();
    const pageA = shared.page();
    const store = await pageA.api.createRowStore(pageA.options);
    await store.append(rows(0, 3));
    assert.equal(store.inMemory, true, 'a small result lives in memory until it is saved');
    const saved = await store.persist();
    assert.equal(saved.count, 3);
    assert.match(saved.id, /^rows-/);
    assert.equal(store.inMemory, false);
    assert.ok(shared.storage.databases.has(DATABASE + saved.id));
    assert.equal(store.retain(Object.assign({}, KEPT, { owner: pageA.api.rowStoreDocumentOwner })), true);
    assert.equal(entryOf(shared.localStorage, saved.id).retained.tabId, 't1');

    pageA.unload();
    await store.dispose();
    assert.ok(shared.storage.databases.has(DATABASE + saved.id), 'leaving the page keeps a saved result');
    assert.equal(entryOf(shared.localStorage, saved.id).dispose, undefined, 'and does not flag it for cleanup');

    const pageB = shared.page();
    const reopened = await pageB.api.openRowStore(saved, pageB.options);
    assert.equal(await reopened.count(), 3);
    assert.deepEqual(values(await reopened.read(0, 10)), ['0', '1', '2']);
    await reopened.append(rows(3, 5));
    assert.deepEqual(values(await reopened.read(1, 10)), ['1', '2', '3', '4']);
    const again = await reopened.persist();
    assert.equal(again.count, 5);
    assert.equal(again.id, saved.id);
    assert.equal(entryOf(shared.localStorage, saved.id).retained.tabId, 't1', 'its size updates keep what it is kept for');

    await reopened.release();
    assert.ok(shared.storage.databases.has(DATABASE + saved.id), 'releasing keeps it');
    const pageC = shared.page();
    const third = await pageC.api.openRowStore(saved, pageC.options);
    assert.equal(await third.count(), 5);
    await third.dispose();
    assert.ok(!shared.storage.databases.has(DATABASE + saved.id), 'disposing a saved result deletes it');
    assert.equal(entryOf(shared.localStorage, saved.id), null);
});

test('one page at a time has a saved result open: another window is told so', async () => {
    const shared = browser();
    const pageA = shared.page();
    const store = await pageA.api.createRowStore(pageA.options);
    await store.append(rows(0, 2));
    const saved = await store.persist();
    store.retain(KEPT);
    await store.release();

    const pageB = shared.page();
    const opened = await pageB.api.openRowStore(saved, pageB.options);
    const pageC = shared.page();
    await assert.rejects(pageC.api.openRowStore(saved, pageC.options), (error) => error.code === 'busy');
    await opened.release();
    const later = await pageC.api.openRowStore(saved, pageC.options);
    assert.equal(await later.count(), 2, 'once the other page lets it go, this one opens it');
    await later.release();
});

test('a saved result that was deleted is reported gone, and its registry entry forgotten', async () => {
    const shared = browser();
    const pageA = shared.page();
    const store = await pageA.api.createRowStore(pageA.options);
    await store.append(rows(0, 2));
    const saved = await store.persist();
    store.retain(KEPT);
    await store.release();
    shared.storage.databases.delete(DATABASE + saved.id);

    const pageB = shared.page();
    await assert.rejects(pageB.api.openRowStore(saved, pageB.options), (error) => error.code === 'gone');
    assert.equal(entryOf(shared.localStorage, saved.id), null);
    assert.ok(!shared.storage.databases.has(DATABASE + saved.id), 'it is not created again empty');
    await assert.rejects(pageB.api.openRowStore({ id: 'rows-never', count: 1, bytes: 1, created: 1 }, pageB.options),
        (error) => error.code === 'gone');
});

test('a result that is not kept for a tab is still deleted when its page goes', async () => {
    const shared = browser();
    const page = shared.page();
    const store = await page.api.createRowStore(page.options);
    await store.append(rows(0, 2));
    const saved = await store.persist();
    await store.release();
    await new Promise((resolve) => setImmediate(resolve));
    assert.ok(!shared.storage.databases.has(DATABASE + saved.id));
});

test('a saved result keeps its size and what it is kept for in the registry, and can be given up', async () => {
    const shared = browser();
    const page = shared.page();
    const store = await page.api.createRowStore(page.options);
    await store.append(rows(0, 4));
    const saved = await store.persist();
    assert.ok(saved.bytes > 0, 'the registry size of the rows');
    store.retain(KEPT);
    assert.equal(page.api.updateRetainedRowStore(saved.id, { shownAt: 42, rows: 4 }), true);
    assert.equal(entryOf(shared.localStorage, saved.id).retained.shownAt, 42);
    await store.release();
    assert.equal(page.api.discardRowStore(saved.id), true);
    assert.equal(entryOf(shared.localStorage, saved.id).dispose, true);
    await assert.rejects(page.api.openRowStore(saved, page.options), (error) => error.code === 'gone');
});

test('a saved result cannot be opened under a shared memory budget', async () => {
    const shared = browser();
    const page = shared.page();
    const options = Object.assign({ memoryBudget: page.api.createRowStoreBudget(1 << 20) }, page.options);
    await assert.rejects(page.api.openRowStore({ id: 'rows-x', count: 1, bytes: 1, created: 1 }, options),
        /memory budget/);
});
